import React, {useState} from 'react';

import {yupResolver} from '@hookform/resolvers/yup';
import {useNavigation, useRoute} from '@react-navigation/native';
import {
  Controller,
  FormProvider,
  useForm,
  useFormContext,
} from 'react-hook-form';
import {useTranslation} from 'react-i18next';
import {KeyboardTypeOptions, View} from 'react-native';
import {KeyboardAwareScrollView} from 'react-native-keyboard-aware-scroll-view';
import {SafeAreaView, useSafeAreaInsets} from 'react-native-safe-area-context';
import {useDispatch} from 'react-redux';
import * as yup from 'yup';
import PicDateView from '../../document-list/components/ModalFilter/components/PicDateView';
import Picker from '../../document-share/tabScreens/shareScreen/components/Picker';
import CardInfoRecipient from './components/CardInfoRecipient';
import CheckBoxText from './components/CheckBoxText';
import ModalFrequent from './components/ModalFrequent';
import {FREQUENT} from './helper';
import styles from './styles';
import {DateUtils} from '../../../../utils';
import TextCM from '../../../../components/Text';
import TextField from '../../../../components/TextField';
import HeaderCM from '../../../../components/Header/HeaderCM';
import ButtonCM from '../../../../components/Button';
import {Color, NavigationName} from '../../../../constants';
import Toast from 'react-native-toast-message';
import {
  ItemType,
  MainItemType,
} from '../../../../navigation/SideMenu/components/CustomDrawerContent/helper';
import {IconBlueHardDisk} from '../../../../assets/images';
import {useDocumentStore} from '../../../../navigation/SideMenu/store/app-store';
import {useDocumentServices} from '../../../../hook/apiHook/useApi';

const ConfirmInfoDocument = () => {
  const {t} = useTranslation();

  const schema = yup.object().shape({
    dueIndays: yup.string().required(t('SU.fieldRequired')),
    message: yup.string(),
  });
  const navigation = useNavigation<any>();

  const insets = useSafeAreaInsets();

  const route = useRoute<any>();

  const dataRoute: any = route.params.data;

  const methods = useForm({
    mode: 'onBlur',
    resolver: yupResolver(schema),
    defaultValues: {
      dueIndays: dataRoute?.dueInDays?.toString(),
    },
  });

  const formData = dataRoute?.header?.fields.filter(
    (item: any) => item.type !== 'Base64',
  );

  const [loadingConfirm, setLoadingConfirm] = useState(false);

  const [loadingSave, setLoadingSave] = useState(false);

  const [renewal, setRenewal] = useState(false);

  const [reminderDate, setreminderDate] = useState(
    DateUtils.addMonths(new Date(), 5),
  );
  const [expDate, setExpDate] = useState(DateUtils.addMonths(new Date(), 6));

  const [frequent, setFrequent] = useState<any>(FREQUENT[0]);

  const [showModalFrequent, setShowModalFrequent] = useState(false);

  const [renewalMessage, setRenewalMessage] = useState('');

  const {
    updateCurrentFocused,
    updateMainCurrentFocused,
    updateArrayMainCurrentFocused,
    reloadDataFn,
  } = useDocumentStore();
  const DocumentServices = useDocumentServices();

  const toggleModalFrequent = () => {
    setShowModalFrequent(!showModalFrequent);
  };

  const renderConfirmDocument = () => {
    return (
      <View style={styles.configImageCtn}>
        <TextCM style={styles.txt16}>
          {t('CD.singleCreate.confirmInfoDocument')}
        </TextCM>
        <Picker
          viewIconRight={<View />}
          label={t('DC.TxtNameDocument')}
          value={dataRoute?.name}
          type="inactive"
        />
        <YupTextField
          controlName={'message'}
          label={t('CD.singleCreate.contentAllParticipant')}
          maxLength={100}
          multiline={true}
        />
        <YupTextField
          controlName={'dueIndays'}
          label={t('CD.singleCreate.dateExpireSign')}
          KeyboardTypeOptions="numeric"
        />
      </View>
    );
  };

  const renderCommonInfoDocument = () => {
    return (
      <View>
        <View style={styles.seperateView} />
        <View style={styles.configImageCtn}>
          <TextCM style={styles.txt16}>
            {t('CD.singleCreate.confirmInfoDocument')}
          </TextCM>
          {formData.map((item: any) => {
            let val = item.value;
            if (item.type === 'Date') {
              val = DateUtils.convertDateToDDMMYYYY(item.value);
            }
            if (item.type === 'Boolean') {
              val =
                item.value === 'true'
                  ? t('CD.singleCreate.yes')
                  : t('CD.singleCreate.no');
            }

            if (item?.id === 'envSubmittedFrom') {
              val = dataRoute?.parties.find(
                (item: any) => item.type === 'my-organization',
              )?.name;
            }
            return (
              <Picker
                key={item?.id}
                label={item?.name?.trim()}
                value={val}
                type="inactive"
              />
            );
          })}
          <CheckBoxText
            value={renewal}
            text={t('CD.singleCreate.reminderRenewal')}
            onPress={() => setRenewal(!renewal)}
          />
          {renewal && (
            <View style={styles.renewal}>
              <PicDateView
                label={t('CD.singleCreate.dateExpiredDocument')}
                date={expDate}
                onChangeDate={setExpDate}
              />
              <PicDateView
                label={t('CD.singleCreate.dateStartRemind')}
                date={reminderDate}
                onChangeDate={setreminderDate}
              />
              <Picker
                viewIconRight={true}
                label={t('CD.singleCreate.frequentReminder')}
                value={frequent.label}
                onPress={toggleModalFrequent}
              />
              <TextField
                label={t('CD.singleCreate.contentRenewal')}
                multiline={true}
                maxLength={100}
                onChangeText={setRenewalMessage}
              />
            </View>
          )}
        </View>
      </View>
    );
  };

  const renderCardInfoRecipient = () => {
    return (
      <View>
        <View style={styles.seperateView} />
        <View style={styles.configImageCtn}>
          <TextCM style={styles.txt16}>
            {t('CD.singleCreate.listRenewal')}
          </TextCM>
          {dataRoute.parties.map((item: any) => {
            return <CardInfoRecipient data={item} key={item.id} />;
          })}
        </View>
      </View>
    );
  };

  const onSubmit = async () => {
    try {
      setLoadingConfirm(true);
      dataRoute.dueInDays = parseFloat(methods.getValues('dueIndays'));
      dataRoute.requester.message = methods.getValues('message');
      const body = {...dataRoute};
      const response = await DocumentServices.updateIdentifySignatory(
        dataRoute.id,
        body,
      );
      if (response) {
        response.data.favourite = [];
        response.data.flowStartDate = new Date().toISOString();
        response.data.header.status = 'processing';
        response.data.status = 'processing';
        await DocumentServices.putEnvelop(
          response.data,
          response?.data?.id,
          'processing',
        );

        if (renewal) {
          const payload = {
            id: null,
            resourceId: dataRoute?.id,
            resourceType: dataRoute?.resourceType,
            resourceName: dataRoute?.name,
            resourceStatus: dataRoute?.status,
            owner: dataRoute?.owner,
            orgIn: dataRoute?.orgIn,
            custId: dataRoute?.custId,
            expDate: expDate,
            reminderDate: reminderDate,
            reminderMonth: null,
            frequency: '1',
            message: renewalMessage,
            finishDate: null,
            createdDate: null,
            createdBy: dataRoute?.createdBy,
            lastModifiedBy: null,
            lastModifiedDate: null,
            status: null,
            countCheck: null,
          };
          const res = await DocumentServices.renewalContract(payload);

          Toast.show({
            type: 'success',
            text1: t('CD.singleCreate.reminderRenewalSuccess'),
          });
        }
        if (renewal) {
          setTimeout(() => {
            Toast.show({
              type: 'success',
              text1: t('CD.singleCreate.createSuccess'),
            });
          }, 4000);
        } else {
          Toast.show({
            type: 'success',
            text1: t('CD.singleCreate.createSuccess'),
          });
        }

        updateCurrentFocused(ItemType.Inprogress);
        updateMainCurrentFocused(MainItemType.MainDocument);
        updateArrayMainCurrentFocused(MainItemType.MainDocument);
        reloadDataFn();

        navigation.navigate(NavigationName.DocumentScreen, {
          screen: NavigationName.DocumentListScreen,
        });
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.TxtSystemError'),
      });
    } finally {
      setLoadingConfirm(false);
    }
  };

  const onSaveAction = async () => {
    try {
      setLoadingSave(true);
      dataRoute.dueInDays = parseFloat(methods.getValues('dueIndays'));
      dataRoute.requester.message = methods.getValues('message');
      const body = {...dataRoute};
      const response = await DocumentServices.updateIdentifySignatory(
        dataRoute.id,
        body,
      );
      if (renewal) {
        const payload = {
          id: null,
          resourceId: dataRoute?.id,
          resourceType: dataRoute?.resourceType,
          resourceName: dataRoute?.name,
          resourceStatus: dataRoute?.status,
          owner: dataRoute?.owner,
          orgIn: dataRoute?.orgIn,
          custId: dataRoute?.custId,
          expDate: expDate,
          reminderDate: reminderDate,
          reminderMonth: null,
          frequency: '1',
          message: renewalMessage,
          finishDate: null,
          createdDate: null,
          createdBy: dataRoute?.createdBy,
          lastModifiedBy: null,
          lastModifiedDate: null,
          status: null,
          countCheck: null,
        };
        const res = await DocumentServices.renewalContract(payload);
      }

      Toast.show({
        type: 'success',
        text1: t('DC.SaveSuccess'),
      });
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.TxtSystemError'),
      });
    } finally {
      setLoadingSave(false);
    }
  };

  return (
    <SafeAreaView
      edges={['bottom']}
      style={[styles.container, {paddingBottom: insets.bottom}]}>
      <HeaderCM title={t('CD.singleCreate.label')} />
      <KeyboardAwareScrollView>
        <FormProvider {...methods}>
          {renderConfirmDocument()}
          {renderCommonInfoDocument()}
          {renderCardInfoRecipient()}
        </FormProvider>
      </KeyboardAwareScrollView>
      <View style={styles.groupButton}>
        <ButtonCM
          loading={loadingSave}
          type="white"
          style={{flex: 1}}
          label={t('CD.saveOperation')}
          viewIconLeft={<IconBlueHardDisk width={24} height={24} />}
          onPress={onSaveAction}
        />
        <ButtonCM
          loading={loadingConfirm}
          style={{flex: 1}}
          label={t('CD.sendDocument')}
          onPress={onSubmit}
        />
      </View>
      {showModalFrequent && (
        <ModalFrequent
          onClose={toggleModalFrequent}
          isVisible={showModalFrequent}
          data={FREQUENT}
          onSubmit={setFrequent}
          currentSelected={frequent}
        />
      )}
    </SafeAreaView>
  );
};

type TextFieldProps = {
  controlName: string;
  label: string;
  maxLength?: number;
  onPressIconRight?: () => void;
  viewIconRight?: React.ReactNode;
  isDisabled?: boolean;
  editable?: boolean;
  isRequired?: boolean;
  paramRef?: React.Ref<any>;
  KeyboardTypeOptions?: KeyboardTypeOptions;
  multiline?: boolean;
};

const YupTextField = ({
  controlName,
  label,
  maxLength,
  onPressIconRight,
  viewIconRight,
  isRequired,
  editable,
  paramRef,
  KeyboardTypeOptions,
  multiline,
}: TextFieldProps) => {
  const {
    control,
    formState: {errors},
  } = useFormContext();

  return (
    <View>
      <Controller
        control={control}
        name={controlName}
        render={({field: {onChange, onBlur, value}}) => {
          return (
            <TextField
              ref={paramRef}
              label={label}
              placeholder={label}
              value={value}
              onBlur={onBlur}
              onChangeText={onChange}
              onIconPress={onPressIconRight}
              maxLength={maxLength}
              errorMessage={errors[controlName]?.message as string}
              viewIconRight={viewIconRight}
              inputContainerStyle={{backgroundColor: Color.White}}
              editable={editable}
              isRequired={isRequired}
              // styleIconRight={{width: 'auto'}}
              keyboardType={KeyboardTypeOptions}
              multiline={multiline}
            />
          );
        }}
      />
    </View>
  );
};

export default ConfirmInfoDocument;
