import {TouchableOpacity, View} from 'react-native';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {FC} from 'react';
import TextCM from '../../../../../../../../../components/Text';

export enum TypeTabs {
  ART,
  INPUT,
}

type Props = {
  onChangeTabs: (value: TypeTabs) => void;
  selected: TypeTabs;
};

const TabsComponent: FC<Props> = ({selected = TypeTabs.ART, onChangeTabs}) => {
  const {t} = useTranslation();

  return (
    <View style={styles.ctnMain}>
      <TouchableOpacity
        onPress={() => onChangeTabs(TypeTabs.ART)}
        style={styles.centerBox}>
        <TextCM
          style={[
            styles.textBtn,
            selected === TypeTabs.ART && styles.textBtnSelect,
          ]}>
          {t('NT.tabs.art')}
        </TextCM>
      </TouchableOpacity>
      <TouchableOpacity
        onPress={() => onChangeTabs(TypeTabs.INPUT)}
        style={styles.centerBox}>
        <TextCM
          style={[
            styles.textBtn,
            selected === TypeTabs.INPUT && styles.textBtnSelect,
          ]}>
          {t('NT.tabs.input')}
        </TextCM>
      </TouchableOpacity>
    </View>
  );
};

export default TabsComponent;
