import React from 'react';
import {useTranslation} from 'react-i18next';
import {
  StyleProp,
  TextStyle,
  TouchableOpacity,
  View,
  ViewStyle,
} from 'react-native';
import styles from './styles';
import TextCM from '../../../../../../../components/Text';
import {IconGreyDownArrow} from '../../../../../../../assets/images';

type Props = {
  isRequired?: boolean;
  value?: any;
  label: string;
  onPress?: () => void;
  viewIconRight?: React.ReactNode;
  viewIconLeft?: React.ReactNode;
  styleContainer?: StyleProp<ViewStyle>;
  styleInput?: StyleProp<TextStyle>;
  type?: 'inactive' | 'active';
  disabled?: boolean;
};

const Picker = ({
  label,
  value,
  onPress,
  isRequired,
  viewIconRight,
  viewIconLeft,
  styleContainer,
  styleInput,
  type = 'active',
  disabled = false,
}: Props) => {
  const {t} = useTranslation();

  const handleOnpress = () => {
    if (onPress) {
      onPress();
    }
  };

  return (
    <TouchableOpacity
      disabled={disabled}
      style={[
        styles.btnPicType,
        type === 'inactive' && {backgroundColor: '#EAECF0'},
        styleContainer,
      ]}
      onPress={handleOnpress}>
      <View style={styles.flex1Left}>
        {viewIconLeft && viewIconLeft}
        {value ? (
          <View style={styles.flex1}>
            <View style={styles.rowCtn}>
              <TextCM
                style={[
                  styles.txtLabel,
                  type === 'inactive' && {color: '#667085'},
                ]}>
                {label}
              </TextCM>
              {isRequired && (
                <TextCM style={styles.requiredIndicator}>*</TextCM>
              )}
            </View>
            <TextCM
              numberOfLines={1}
              style={[
                styles.txtType,
                type === 'inactive' && {color: '#667085'},
                styleInput,
              ]}>
              {value}
            </TextCM>
          </View>
        ) : (
          <View style={styles.rowCtn}>
            <TextCM
              style={[
                styles.txtNoType,
                type === 'inactive' && {color: '#667085'},
                styleInput,
              ]}>
              {label}
            </TextCM>
            {isRequired && (
              <TextCM style={[styles.requiredIndicator, {fontSize: 14}]}>
                *
              </TextCM>
            )}
          </View>
        )}
      </View>
      {viewIconRight ? <IconGreyDownArrow width={24} height={24} /> : null}
    </TouchableOpacity>
  );
};

export default Picker;
