import {DrawerContentScrollView} from '@react-navigation/drawer';
import {DrawerActions, useNavigation} from '@react-navigation/native';
import React, {useEffect} from 'react';
import {useTranslation} from 'react-i18next';
import {ScrollView, TouchableOpacity, View} from 'react-native';
import {
  ItemMenuType,
  ItemType,
  MainItemType,
  getIcon,
  getListItem,
  getListItemDrawer,
} from './helper';
import styles from './styles';
import TextCM from '../../../../components/Text';
import {Font, NavigationName, String} from '../../../../constants';
import {
  IconBlackRightArrow,
  IconBrandWithText,
} from '../../../../assets/images';
import {useAppSelector} from '../../../../hook/useRedux';
import {useDocumentStore} from '../../store/app-store';
import {Icon} from '@ui-kitten/components';

const CustomDrawerContent = (props: any) => {
  const {t} = useTranslation();
  const {
    currentFocused,
    mainCurrentFocused,
    mainArrayCurrentFocused,
    currentFocusOrganization,
    updateCurrentFocused,
    updateMainCurrentFocused,
    updateArrayMainCurrentFocused,
    showSortOrganization,
  } = useDocumentStore();
  const navigation = useNavigation();

  const user = useAppSelector(state => state.account.dataAccount);

  const checkIsFocus = (item: ItemMenuType) => {
    return item.type === currentFocused;
  };

  const onPressItem = (item: ItemMenuType) => {
    updateCurrentFocused(item.type);
    if (
      item.type === ItemType.InprogressDocumentOrganization ||
      item.type === ItemType.DoneDocumentOrganization ||
      item.type === ItemType.CancelDocumentOrganization ||
      item.type === ItemType.RejectDocumentOrganization ||
      item.type === ItemType.ExpiredDocumentOrganization
    ) {
      updateMainCurrentFocused(MainItemType.MainDocumentOrganization);
    }
    navigation.dispatch(DrawerActions.toggleDrawer());
    if (item.type === ItemType.Authen) {
      navigation.navigate(NavigationName.DocumentVerifyScreen as never);
    } else {
      navigation.navigate(NavigationName.DocumentListScreen as never);
    }
  };

  const onPressMainItem = (item: any) => {
    updateMainCurrentFocused(item.type);
    updateArrayMainCurrentFocused(item.type);
  };

  useEffect(() => {
    if (
      mainCurrentFocused === MainItemType.MainDocument &&
      mainArrayCurrentFocused.includes(MainItemType.MainDocument)
    ) {
      updateCurrentFocused(ItemType.Inprogress);
    } else if (
      mainCurrentFocused === MainItemType.MainDocumentTemplate &&
      mainArrayCurrentFocused.includes(MainItemType.MainDocumentTemplate)
    ) {
      updateCurrentFocused(ItemType.MyDocumentTemplate);
    } else if (
      mainCurrentFocused === MainItemType.MainDocumentOrganization &&
      mainArrayCurrentFocused.includes(MainItemType.MainDocumentOrganization)
    ) {
      updateCurrentFocused(ItemType.InprogressDocumentOrganization);
    } else {
      updateCurrentFocused(currentFocused);
    }
  }, [mainArrayCurrentFocused]);

  const onPressOrganization = () => {
    navigation.dispatch(DrawerActions.toggleDrawer());
    updateCurrentFocused(ItemType.InprogressDocumentOrganization);
    showSortOrganization(true);
  };

  const renderItem = (item: ItemMenuType) => {
    return (
      <TouchableOpacity
        style={[checkIsFocus(item) && styles.viewItemActive]}
        key={item.type}
        onPress={() => {
          onPressItem(item);
        }}>
        <View
          style={[
            styles.viewItem,
            checkIsFocus(item) && {
              backgroundColor: item.bgColor,
            },
          ]}>
          {item.type !== ItemType.MyDocumentTemplate &&
            item.type !== ItemType.TemplateShare && (
              <View style={styles.viewIcon}>
                {getIcon(item.type, currentFocused)}
              </View>
            )}
          <TextCM
            style={[
              styles.txtItem,
              checkIsFocus(item) && {
                color: item.textColor,
                fontFamily: Font.InterSemiBold600,
              },
            ]}>
            {t(`${item.title}`)}
          </TextCM>
        </View>
      </TouchableOpacity>
    );
  };

  const renderItemMain = (item: any, index: number) => {
    const newData = item?.subItem;
    return (
      <View key={index}>
        <TouchableOpacity
          activeOpacity={0.8}
          style={styles.ctnMainItem}
          onPress={() => onPressMainItem(item)}>
          <View style={styles.ctnElement}>
            <View style={styles.ctnLeftMainItem}>
              {item.icon}
              <TextCM style={styles.txtItem}>{t(`${item.title}`)}</TextCM>
            </View>
            <View
              style={{
                transform: mainArrayCurrentFocused.includes(item.type)
                  ? [{rotate: '90deg'}]
                  : [],
              }}>
              <IconBlackRightArrow width={14} height={14} />
            </View>
          </View>
        </TouchableOpacity>
        {item.type === MainItemType.MainDocumentOrganization &&
          mainArrayCurrentFocused.includes(
            MainItemType.MainDocumentOrganization,
          ) && (
            <View style={styles.ctnOrganization}>
              <TextCM style={styles.txtOrganization}>
                {t('SM.TxtOrganization')}
              </TextCM>
              <TouchableOpacity
                onPress={onPressOrganization}
                style={styles.ctnChooseOrganization}>
                <TextCM
                  numberOfLines={1}
                  style={[
                    styles.txtOrganization,
                    styles.txtChooseOrganization,
                  ]}>
                  {currentFocusOrganization !== null
                    ? currentFocusOrganization?.acName
                    : t('SM.TxtOrganization')}
                </TextCM>
                <IconBlackRightArrow width={14} height={14} />
              </TouchableOpacity>
            </View>
          )}
        {mainArrayCurrentFocused.includes(item.type)
          ? newData.map(renderItem)
          : null}
      </View>
    );
  };

  const includesBoth =
    user?.authorities?.includes(String.ROLE.ROLE_CUST_VIEWER) ||
    user?.authorities?.includes(String.ROLE.ROLE_ORG_ADMIN);

  const handleCreateDocument = () => {
    navigation.navigate(NavigationName.InfomationDocumentScreen as never);
    updateCurrentFocused(ItemType.Done);
    updateMainCurrentFocused(MainItemType.MainDocument);
    navigation.dispatch(DrawerActions.toggleDrawer());
  };

  return (
    <DrawerContentScrollView
      {...props}
      contentContainerStyle={styles.container}>
      <View style={styles.viewLogo}>
        <IconBrandWithText width={173} height={38} />
      </View>
      <ScrollView showsVerticalScrollIndicator={false}>
        <View style={styles.viewContent}>
          {/* <TouchableOpacity
            onPress={handleCreateDocument}
            activeOpacity={0.8}
            style={styles.ctnCreateDocument}>
            <IconCreateDocument width={(24)} height={(24)} />
            <TextCM style={styles.txtCreateDocument}>
              {t('HM.TxtCreateDocument')}
            </TextCM>
          </TouchableOpacity>
          <View style={styles.line} /> */}
          {includesBoth
            ? getListItemDrawer.map((item: any, index) => {
                return renderItemMain(item, index);
              })
            : getListItemDrawer.map((item, index) => {
                if (item.type !== MainItemType.MainDocumentOrganization) {
                  return renderItemMain(item, index);
                }
              })}
        </View>
      </ScrollView>
    </DrawerContentScrollView>
  );
};

export default CustomDrawerContent;
