import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {
  FlatList,
  Modal,
  RefreshControl,
  StyleProp,
  TouchableOpacity,
  View,
  ViewStyle,
} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import styles from './styles';

import {debounce} from 'lodash';
import ModalListOrg from '../ModalListOrg';
import {IFinderRecipient} from '../../../../../model/interface/envelope.interface';
import {
  IcBlackLeftArrow,
  IconBlackSearch,
  IconBlueCheck,
  IconGreyDownArrow,
} from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';
import TextField from '../../../../../components/TextField';
import {Color} from '../../../../../constants';
import ButtonCM from '../../../../../components/Button';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';

type ModalFindRecipientProp = {
  onClose: () => void;
  isVisible: boolean;
  onSelected: (item: IFinderRecipient) => void;
  styleContainer?: StyleProp<ViewStyle>;
};

const ModalFindRecipient = ({
  onClose,
  isVisible,
  onSelected,
  styleContainer,
}: ModalFindRecipientProp) => {
  const {t} = useTranslation();
  const insets = useSafeAreaInsets();
  const [data, setData] = useState<IFinderRecipient[]>([]);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [debouncedSearchText, setDebouncedSearchText] = useState('');
  const [searchText, setSearchText] = useState('');
  const [totalPage, setTotalPage] = useState(1);
  const [page, setPage] = useState(0);
  const [selectedRecipient, setSelectedRecipient] =
    useState<IFinderRecipient | null>(null);
  const [showModalListOrg, setShowModalListOrg] = useState(false);

  // orgnization
  const [listOrg, setListOrg] = useState<any[]>([{label: t('DC.all'), id: ''}]);
  const [selectedOrg, setSelectedOrg] = useState({label: t('DC.all'), id: ''});
  const DocumentServices = useDocumentServices();
  const debouncedSearch = debounce((text: string) => {
    setDebouncedSearchText(text);
  }, 300);

  useEffect(() => {
    debouncedSearch(searchText);
    return () => {
      debouncedSearch.cancel();
    };
  }, [searchText]);

  useEffect(() => {
    getData(0, debouncedSearchText, selectedOrg.id);
  }, [debouncedSearchText, selectedOrg]);

  useEffect(() => {
    getAllOrg();
  }, []);

  const getAllOrg = async () => {
    const res = await DocumentServices.getAllOrg();
    setListOrg(prev => [
      ...prev,
      ...res.map(item => ({label: item.name, id: item.orgIn})),
    ]);
  };

  const getData = async (page = 0, keySearch = '', org = '') => {
    try {
      const res = await DocumentServices.getListRecipients(
        keySearch,
        org,
        page,
      );
      if (page) {
        setData(prev => [...prev, ...res.data]);
      } else {
        setPage(0);
        setData(res.data);
      }
      setTotalPage(res.totalPage);
    } catch (error) {
    } finally {
      setIsRefreshing(false);
    }
  };

  const onPressItem = (item: IFinderRecipient) => {
    setSelectedRecipient(item);
  };

  const renderItem = ({item}: {item: IFinderRecipient}) => {
    return (
      <CardItem
        onPress={onPressItem}
        data={item}
        isSelected={item.id === selectedRecipient?.id}
      />
    );
  };

  const onEndReached = async () => {
    if (totalPage > 1 && page + 1 < totalPage) {
      getData(page + 1, debouncedSearchText, selectedOrg.id);
      setPage(page + 1);
    }
  };

  const onRefresh = async () => {
    setIsRefreshing(true);
    getData(0, debouncedSearchText, selectedOrg.id);
  };

  const toggleModalListOrg = () => {
    setShowModalListOrg(!showModalListOrg);
  };

  const handleOnsubmit = () => {
    if (selectedRecipient) {
      onSelected(selectedRecipient);
      onClose();
    }
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <View style={[styles.ctnContainer, styleContainer]}>
        <View style={styles.ctnTop} onTouchEnd={onClose} />
        <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <View style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={14} height={16} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>{t('DC.searchForUser')}</TextCM>
            <View />
          </View>
          <View style={styles.viewBody}>
            <TextField
              label={t('DC.typeInfoUser')}
              placeholder={t('DC.typeInfoUser')}
              onChangeText={setSearchText}
              viewIconRight={<IconBlackSearch width={16} height={16} />}
            />
            <TextField
              inputContainerStyle={{backgroundColor: Color.White}}
              isDisabled
              label={t('AI.TxtOrganizationInfo')}
              placeholder={t('AI.TxtOrganizationInfo')}
              viewIconRight={<IconGreyDownArrow width={16} height={16} />}
              onIconPress={toggleModalListOrg}
              value={selectedOrg.label}
            />
            <FlatList
              data={data}
              keyExtractor={item => item.id}
              renderItem={renderItem}
              contentContainerStyle={styles.ctnFlatList}
              onEndReached={onEndReached}
              onEndReachedThreshold={0.5}
              refreshControl={
                <RefreshControl
                  refreshing={isRefreshing}
                  onRefresh={onRefresh}
                />
              }
              ListEmptyComponent={<Nodata />}
            />
            <ButtonCM
              disabled={selectedRecipient === null}
              onPress={handleOnsubmit}
              label={t('CM.TxtSave')}
            />
          </View>
        </View>
      </View>
      <ModalListOrg
        onPress={setSelectedOrg}
        data={listOrg}
        onClose={toggleModalListOrg}
        isVisible={showModalListOrg}
        itemSelected={selectedOrg}
      />
    </Modal>
  );
};

export default ModalFindRecipient;

const CardItem = ({
  data,
  isSelected = false,
  onPress,
}: {
  data: IFinderRecipient;
  isSelected: Boolean;
  onPress?: (item: IFinderRecipient) => void;
}) => {
  const {t} = useTranslation();

  const handleOnpress = () => {
    if (onPress) {
      onPress(data);
    }
  };
  return (
    <TouchableOpacity
      onPress={handleOnpress}
      style={[styles.cardView, isSelected && {backgroundColor: '#E6F2FB'}]}>
      <View style={styles.rowInfo}>
        <TextCM style={[styles.txtSmall600, isSelected && {color: '#0673C6'}]}>
          {data.personalName}
        </TextCM>
        {isSelected && <IconBlueCheck width={16} height={16} />}
      </View>
      <View style={styles.rowInfo}>
        <TextCM style={styles.txtSmall400}>
          {t('AI.TxtOrganizationInfo')}
        </TextCM>
        <TextCM style={styles.txtInfo}>{data?.orgName}</TextCM>
      </View>
      <View style={styles.rowInfo}>
        <TextCM style={styles.txtSmall400}>{t('DC.position')}</TextCM>
        <TextCM>{data?.role ? data?.role : '---'}</TextCM>
      </View>
      <View style={styles.rowInfo}>
        <TextCM style={styles.txtSmall400}>{t('AI.TxtEmail')}</TextCM>
        <TextCM style={styles.txtInfo}>{data?.email}</TextCM>
      </View>
      <View style={styles.rowInfo}>
        <TextCM style={styles.txtSmall400}>{t('AI.TxtPhone')}</TextCM>
        <TextCM style={styles.txtInfo}>{data?.phone}</TextCM>
      </View>
    </TouchableOpacity>
  );
};

const Nodata = () => {
  const {t} = useTranslation();
  return <TextCM style={styles.txtNoData}>{t('DC.TxtNoData')}</TextCM>;
};
