import {debounce, isEmpty} from 'lodash';
import React, {useEffect, useRef, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {FlatList, RefreshControl, View} from 'react-native';
import InputSearch from '../../../document-list/components/InputSearch';
import ModalFilter from '../../../document-list/components/ModalFilter';
import DocumentAuthenItem from '../../components/AuthenDocumentItem';
import {getEnvelopeCecaPath, IAuthenDocumentTab} from '../../helper';
import styles from './styles';
import {
  IDocument,
  IOrganization,
} from '../../../../../model/interface/envelope.interface';
import {useDocumentStore} from '../../../../../navigation/SideMenu/store/app-store';
import {useAppSelector} from '../../../../../hook/useRedux';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';
import TextCM from '../../../../../components/Text';

const DocumetnAuthenListScreen = ({tab}: {tab: IAuthenDocumentTab}) => {
  const {currentFocused, reloadData} = useDocumentStore();
  const account = useAppSelector(state => state.account.dataAccount);
  const [searchText, setSearchText] = useState('');
  const [debouncedSearchText, setDebouncedSearchText] = useState('');
  const [data, setData] = useState<IDocument[] & IOrganization[]>([]);
  const [totalPage, setTotalPage] = useState(1);
  const [page, setPage] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isShowFilter, setIsShowFilter] = useState(false);
  const [filterData, setFilterData] = useState<any>({});

  const refFlatList = useRef<any>();
  const DocumentServices = useDocumentServices();
  const debouncedSearch = debounce((text: string) => {
    setDebouncedSearchText(text);
  }, 300);

  useEffect(() => {
    debouncedSearch(searchText);
    return () => {
      debouncedSearch.cancel();
    };
  }, [searchText]);

  useEffect(() => {
    getData(0, debouncedSearchText, filterData);
  }, [currentFocused, debouncedSearchText, filterData, reloadData]);

  useEffect(() => {
    if (!isEmpty(filterData) || searchText) {
      resetData();
    }
    if (data.length > 0) {
      refFlatList.current?.scrollToOffset({animated: true, offset: 0});
    }
  }, [currentFocused]);

  const resetData = () => {
    setSearchText('');
    setDebouncedSearchText('');
    setFilterData({});
  };

  const getData = async (
    page = 0,
    keyWord = '',
    filterData?: {sort: any; search: any; sort2?: string} | undefined,
  ) => {
    const pathApt = getEnvelopeCecaPath(tab, account.email);
    const params = {
      page,
      size: 10,
      search: JSON.stringify({
        keyWord,
        envelopeCecaRegistrySearch: {
          ...pathApt.params.envelopeCecaRegistrySearch,
        },
        ...filterData?.search,
      }),
    };

    const data = await DocumentServices.getData(pathApt.path, params, {
      sort: filterData?.sort ? filterData.sort : pathApt.params.sort,
      sort2: filterData?.sort2,
    });

    var newData = data.data;

    if (page) {
      setData(prev => [...prev, ...newData]);
    } else {
      setPage(0);
      setData(newData);
    }
    setTotalPage(data.totalPage);
    setIsRefreshing(false);
  };

  const renderItem = ({item}: {item: IDocument & IOrganization}) => {
    return <DocumentAuthenItem tabKey={tab} data={item} />;
  };

  const onEndReached = async () => {
    if (totalPage > 1 && page + 1 < totalPage) {
      getData(page + 1, debouncedSearchText, filterData);
      setPage(page + 1);
    }
  };

  const onRefresh = async () => {
    setIsRefreshing(true);
    getData(0, debouncedSearchText, filterData);
  };

  const toggleShowFilter = () => {
    setIsShowFilter(!isShowFilter);
  };

  const onFilter = (data: any) => {
    setFilterData(data);
  };

  return (
    <View style={styles.ctnMain}>
      <InputSearch
        setSearchText={setSearchText}
        searchText={searchText}
        onPressFilter={toggleShowFilter}
      />
      <FlatList
        data={data}
        ref={refFlatList}
        keyExtractor={item => item.id}
        renderItem={renderItem}
        contentContainerStyle={styles.body}
        onEndReached={onEndReached}
        refreshControl={
          <RefreshControl refreshing={isRefreshing} onRefresh={onRefresh} />
        }
        ListEmptyComponent={<Nodata />}
      />
      <ModalFilter
        onFilter={onFilter}
        isShowFilter={isShowFilter}
        toggleShowFilter={toggleShowFilter}
        filterData={filterData}
      />
    </View>
  );
};

export default DocumetnAuthenListScreen;

const Nodata = () => {
  const {t} = useTranslation();
  return <TextCM style={styles.txtNoData}>{t('DC.TxtNoData')}</TextCM>;
};
