import {FC, useEffect, useState} from 'react';
import {
  FlatList,
  TouchableOpacity,
  useWindowDimensions,
  View,
} from 'react-native';
import styles from './styles';
import {moveElementToFront, sortListByPriority} from '../../helper';
import {isNull, isUndefined} from 'lodash';
import {useTranslation} from 'react-i18next';
import {ICreateTemplateMessage} from '../../../../../model/interface/notification.interface';
import TextCM from '../../../../../components/Text';
import {
  IconBlackDownArrow,
  IconCheckedRadio,
  IconRadio,
  IconRedFillTrash,
} from '../../../../../assets/images';
import ModalConfirm from '../../../../../components/ModalConfirm';
import {useCreateNotiServices} from '../../../../../hook/apiHook/useApi';

type Props = {
  handleCloseTemplateMessage: (item: ICreateTemplateMessage) => void;
};

const RenderTemplateMessage: FC<Props> = ({handleCloseTemplateMessage}) => {
  const {t} = useTranslation();

  const [isVisibleModal, setIsVisibleModal] = useState<boolean>(false);
  const [listTemplateMessage, setListTemplateMessage] = useState<
    ICreateTemplateMessage[]
  >([]);
  const [listTemplateMessageFilter, setListTemplateMessageFilter] = useState<
    boolean[]
  >([]);
  const [templateMessageSelect, setTemplateMessageSelect] =
    useState<ICreateTemplateMessage>();

  const {height, width} = useWindowDimensions();

  const NotificationServices = useCreateNotiServices();

  useEffect(() => {
    (async () => {
      await getListTemplateMessage();
    })();
  }, []);

  const handleSelectRadio = (item: ICreateTemplateMessage, index: number) => {
    const newDataSelect = listTemplateMessageFilter.map((item, idx) =>
      idx === index ? true : false,
    );
    setListTemplateMessageFilter(newDataSelect);
    setTemplateMessageSelect(item);
    handleCloseTemplateMessage(item);
  };
  const getListTemplateMessage = async () => {
    try {
      const dataResp =
        (await NotificationServices.getTemplateMessage()) as ICreateTemplateMessage[];
      const dataSortByPriority = sortListByPriority(dataResp);
      setListTemplateMessage(dataSortByPriority);
      setListTemplateMessageFilter(
        new Array(dataSortByPriority.length).fill(false),
      );
    } catch (error) {}
  };

  const handleDeleteTemplateMessage = async (id: number | null) => {
    try {
      await NotificationServices.deleteTemplateMessage(id);
      await getListTemplateMessage();
      setIsVisibleModal(false);
    } catch (error) {}
  };

  const createPriority = (list: ICreateTemplateMessage[]) => {
    list.forEach((item, index) => {
      item.priority = index;
    });
    return list;
  };

  const handleUpdatePriotityTemplateMessage = async (
    message: ICreateTemplateMessage,
  ) => {
    if (!isNull(message) && !isUndefined(message)) {
      const _messageTemplate = JSON.parse(JSON.stringify(listTemplateMessage));
      const __messageTemplate = moveElementToFront(
        _messageTemplate,
        message.id,
      ) as ICreateTemplateMessage[];
      setListTemplateMessage(createPriority(__messageTemplate));
      await NotificationServices.updateTemplateMessage(__messageTemplate);
    }
  };

  return (
    <View style={{height: height / 2}}>
      <TextCM>{t('NT.chooseSample')}</TextCM>
      <FlatList
        showsHorizontalScrollIndicator={false}
        showsVerticalScrollIndicator={false}
        data={listTemplateMessage}
        renderItem={({item, index}) => (
          <View style={styles.ctnGroupRadio}>
            <TouchableOpacity
              onPress={() => handleSelectRadio(item, index)}
              style={styles.ctnBody}>
              {!listTemplateMessageFilter[index] ? (
                <IconRadio width={20} height={20} />
              ) : (
                <IconCheckedRadio width={20} height={20} />
              )}
              <TextCM
                style={[
                  styles.txtRadio,
                  {
                    width: width - 120,
                  },
                ]}>
                {item.content}
              </TextCM>
            </TouchableOpacity>
            <View style={styles.ctnBody}>
              {item.id !== listTemplateMessage[0].id && (
                <TouchableOpacity
                  onPress={() => handleUpdatePriotityTemplateMessage(item)}
                  style={{transform: [{rotate: '180deg'}]}}>
                  <IconBlackDownArrow width={14} height={16} />
                </TouchableOpacity>
              )}
              <TouchableOpacity
                onPress={() => {
                  setIsVisibleModal(true);
                  setTemplateMessageSelect(item);
                }}>
                <IconRedFillTrash width={16} height={16} />
              </TouchableOpacity>
            </View>
            <ModalConfirm
              type="delete"
              labelConfirm={t('CM.BtnClear')}
              title={t('NT.agreeClear')}
              isVisible={isVisibleModal}
              onClose={() => setIsVisibleModal(false)}
              onConfirm={() =>
                handleDeleteTemplateMessage(templateMessageSelect!.id)
              }
            />
          </View>
        )}
      />
    </View>
  );
};

export default RenderTemplateMessage;
